<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\SwapStatus;
use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * Item-for-item trade proposal. `cash_adjustment_amount` is signed:
 * positive = proposer pays the counterparty, negative = proposer receives.
 */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $target_listing_id
 * @property string $proposer_id
 * @property string $counterparty_id
 * @property int $cash_adjustment_amount
 * @property string $currency
 * @property int $swap_fee_amount
 * @property string|null $message
 * @property SwapStatus $status
 * @property Carbon $expires_at
 * @property Carbon|null $responded_at
 * @property Carbon|null $counterparty_read_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class SwapRequest extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'swp';

    protected $fillable = [
        'target_listing_id', 'proposer_id', 'counterparty_id', 'cash_adjustment_amount', 'currency', 'swap_fee_amount',
        'message', 'status', 'expires_at', 'responded_at', 'counterparty_read_at',
    ];

    protected function casts(): array
    {
        return [
            'status' => SwapStatus::class,
            'cash_adjustment_amount' => 'integer',
            'swap_fee_amount' => 'integer',
            'expires_at' => 'datetime',
            'responded_at' => 'datetime',
            'counterparty_read_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<Listing, $this> */
    public function targetListing(): BelongsTo
    {
        return $this->belongsTo(Listing::class, 'target_listing_id')->withTrashed();
    }

    /** @return BelongsTo<User, $this> */
    public function proposer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'proposer_id');
    }

    /** @return BelongsTo<User, $this> */
    public function counterparty(): BelongsTo
    {
        return $this->belongsTo(User::class, 'counterparty_id');
    }

    /** @return HasMany<SwapRequestItem, $this> */
    public function items(): HasMany
    {
        return $this->hasMany(SwapRequestItem::class);
    }

    /** @return HasMany<SwapEvent, $this> */
    public function events(): HasMany
    {
        return $this->hasMany(SwapEvent::class)->orderByDesc('occurred_at');
    }

    /** @return HasMany<Order, $this> */
    public function orders(): HasMany
    {
        return $this->hasMany(Order::class);
    }

    public function cashAdjustment(): Money
    {
        return Money::of($this->cash_adjustment_amount, $this->currency);
    }

    public function swapFee(): Money
    {
        return Money::of($this->swap_fee_amount, $this->currency);
    }

    public function isParty(User $user): bool
    {
        return $user->id === $this->proposer_id || $user->id === $this->counterparty_id;
    }
}
